    l.items = l.items.filter(it => !/^[|¦!\[\]_]+$/.test(it.s)).map(it => Object.assign({}, it, {s: it.s.replace(/^[|¦]+\s*|\s*[|¦]+$/g, "")})).filter(it => it.s);
