  if (b.cur === sid){ clearTimeout(bankSaveTimer); bankSaveTimer = null; b.cur = null; b.rows = []; b.sel.clear(); b.sticky.clear(); b.undo = null; }
  toast("Statement deleted. More \u2192 Restore a deleted statement puts it back.");
