    const row = bankRow(id);
    if (row && B().postedTags){ delete B().postedTags[fpHash(row.fp || row.id)]; row.postError = ""; saveBank({rows: true, posted: true}); toast("It will be checked in Tally again, then posted."); render(); }
    return true;
