  if (!R) return;
  const ids = R.missing.filter(id => { const r = b.rows.find(x => x.id === id); return r && ["ready", "sent", "intally"].includes(r.state) && !bankAside(r) && !bankRepOpen(r) && r.ledger && exactLedger(r.ledger); });
  if (!ids.length) return;
