      const got = await this.live("tally_vouchers?select=guid,cancelled&book_id=eq." + encodeURIComponent(bk.book) + "&guid=in.(" + encodeURIComponent(g) + ")");
      (got || []).forEach(x => { if (!x.cancelled) found.add(x.guid); });
