    const ids = CloudJobs.idsOf(j) || [...new Set(items.map(x => String(x.id)).concat(results.map(x => String(x.id))))];
    const live = CloudJobs.live(j), byPerson = !!(j.dismissed_at && !j.dismiss_auto);
