      const k = normName(a.employee), r = by[k] = by[k] || {employee: a.employee, heads: {}, gross: 0, ded: 0, employer: 0, reimb: 0, loan: 0, tds: 0, pt: 0, vouchers: new Set()};
      const kind = this.kind(a.head), v = kind === "ded" || kind === "loan" ? r2(a.amt) : r2(-a.amt);
