    const c = Object.assign({id: uid("ch"), from: "hand", madeBy: "hand", autoPlace: "pending", enteredBy: this.who() || (typeof whoAmI === "function" ? whoAmI() : ""), enteredAt: new Date().toISOString()}, r.c);
